  ProtocolModel(
    id: "balantidiase",
    canonicalProtocolId: "balantidiase",
    title: {"pt": "Balantidíase", "es": "Balantidiasis"},
    severity: {"pt": "Avaliar sinais de alarme", "es": "Evaluar signos de alarma"},
    definition: {"pt": "Balantidium coli é protozoário ciliado transmitido por ingestão de cistos em água ou alimentos contaminados. Suínos são reservatório importante. A infecção pode ser assintomática ou produzir colite ulcerativa e disenteria.", "es": "Balantidium coli es un protozoo ciliado transmitido por ingestión de quistes en agua o alimentos contaminados. Los cerdos son un reservorio importante. La infección puede ser asintomática o producir colitis ulcerativa y disentería."},
    actions: {"pt": ["Balantidium coli é protozoário ciliado transmitido por ingestão de cistos em água ou alimentos contaminados. Suínos são reservatório importante. A infecção pode ser assintomática ou produzir colite ulcerativa e disenteria. [2]", "Identificar trofozoítos ou cistos nas fezes; material deve ser examinado por laboratório habilitado. Diferenciar amebíase, disenteria bacteriana e doença inflamatória intestinal; epidemiologia isolada não confirma o agente. [2]", "Avaliar hidratação, sangramento, dor e sinais de peritonite. Corrigir perdas em paralelo ao diagnóstico; colite invasiva não deve ser tratada somente com antidiarreico. [2]", "Esquema adulto elegível: tetraciclina 500 mg por via oral quatro vezes ao dia durante 10 dias. Tomar 1 hora antes ou 2 horas após alimentos ou laticínios. É contraindicada na gestação e em crianças menores de 8 anos. [1]", "Alternativa adulta: metronidazol 500–750 mg por via oral três vezes ao dia durante 5 dias. Escolher um esquema adequado; não associar rotineiramente tetraciclina e metronidazol. Seleção depende de contraindicações e disponibilidade local. [1]", "Reavaliar hidratação, frequência das evacuações, sangue e resposta. Persistência exige revisão do diagnóstico, adesão e reinfecção. Reforçar saneamento, água segura e higiene após contato com fezes e animais. [2, 1]", "Disenteria importante, desidratação grave, instabilidade ou sinais de perfuração exigem hospital. Alta somente se estável, tolerando líquidos e com tratamento e retorno assegurados. [2]", "Gestação, lactação, crianças e disfunção renal ou hepática precisam escolha individual e conferência da bula. Não extrapolar dose adulta nem substituir tetraciclina por outro fármaco da classe sem evidência específica. [1]"], "es": ["Balantidium coli es un protozoo ciliado transmitido por ingestión de quistes en agua o alimentos contaminados. Los cerdos son un reservorio importante. La infección puede ser asintomática o producir colitis ulcerativa y disentería. [2]", "Identificar trofozoítos o quistes en materia fecal; el material debe ser examinado por laboratorio capacitado. Diferenciar amebiasis, disentería bacteriana y enfermedad inflamatoria intestinal; la epidemiología aislada no confirma el agente. [2]", "Evaluar hidratación, sangrado, dolor y signos de peritonitis. Corregir pérdidas en paralelo al diagnóstico; una colitis invasiva no debe tratarse solo con antidiarreico. [2]", "Esquema adulto elegible: tetraciclina 500 mg por vía oral cuatro veces al día durante 10 días. Tomar 1 hora antes o 2 horas después de alimentos o lácteos. Está contraindicada en embarazo y en menores de 8 años. [1]", "Alternativa adulta: metronidazol 500–750 mg por vía oral tres veces al día durante 5 días. Elegir un esquema adecuado; no asociar rutinariamente tetraciclina y metronidazol. La selección depende de contraindicaciones y disponibilidad local. [1]", "Reevaluar hidratación, frecuencia de evacuaciones, sangre y respuesta. La persistencia exige revisar diagnóstico, adherencia y reinfección. Reforzar saneamiento, agua segura e higiene tras contacto con heces y animales. [2, 1]", "La disentería importante, deshidratación grave, inestabilidad o signos de perforación requieren hospital. Alta solo si está estable, tolera líquidos y tiene tratamiento y seguimiento asegurados. [2]", "Embarazo, lactancia, niños y disfunción renal o hepática requieren selección individual y verificación de ficha técnica. No extrapolar la dosis adulta ni sustituir tetraciclina por otro fármaco de la clase sin evidencia específica. [1]"]},
    avoid: {},
    drugs: [],
    physiopathology: {"pt": "O aspecto de disenteria aproxima balantidíase de outras colites invasivas, mas não identifica o agente. História epidemiológica orienta a coleta; a confirmação laboratorial evita aplicar indevidamente o tratamento de amebíase ou de uma doença inflamatória.", "es": "El aspecto de disentería aproxima la balantidiasis a otras colitis invasivas, pero no identifica el agente. Los antecedentes epidemiológicos orientan la toma de muestras; la confirmación de laboratorio evita aplicar indebidamente el tratamiento de amebiasis o de una enfermedad inflamatoria."},
    references: {"pt": ["[1] CDC. Clinical Treatment of Balantidium coli infection. 2024. https://www.cdc.gov/balantidium/hcp/clinical-care/index.html", "[2] CDC. DPDx: Balantidiasis. 2026. https://www.cdc.gov/dpdx/balantidiasis/index.html"], "es": ["[1] CDC. Clinical Treatment of Balantidium coli infection. 2024. https://www.cdc.gov/balantidium/hcp/clinical-care/index.html", "[2] CDC. DPDx: Balantidiasis. 2026. https://www.cdc.gov/dpdx/balantidiasis/index.html"]},
    exams: {"pt": ["Identificar trofozoítos ou cistos nas fezes; material deve ser examinado por laboratório habilitado. Diferenciar amebíase, disenteria bacteriana e doença inflamatória intestinal; epidemiologia isolada não confirma o agente. [2]"], "es": ["Identificar trofozoítos o quistes en materia fecal; el material debe ser examinado por laboratorio capacitado. Diferenciar amebiasis, disentería bacteriana y enfermedad inflamatoria intestinal; la epidemiología aislada no confirma el agente. [2]"]},
    classification: {"pt": [], "es": []},
    scenarios: {"pt": ["Disenteria importante, desidratação grave, instabilidade ou sinais de perfuração exigem hospital. Alta somente se estável, tolerando líquidos e com tratamento e retorno assegurados. [2]", "Gestação, lactação, crianças e disfunção renal ou hepática precisam escolha individual e conferência da bula. Não extrapolar dose adulta nem substituir tetraciclina por outro fármaco da classe sem evidência específica. [1]"], "es": ["La disentería importante, deshidratación grave, inestabilidad o signos de perforación requieren hospital. Alta solo si está estable, tolera líquidos y tiene tratamiento y seguimiento asegurados. [2]", "Embarazo, lactancia, niños y disfunción renal o hepática requieren selección individual y verificación de ficha técnica. No extrapolar la dosis adulta ni sustituir tetraciclina por otro fármaco de la clase sin evidencia específica. [1]"]},
    objectives: {"pt": ["Avaliar hidratação, sangramento, dor e sinais de peritonite. Corrigir perdas em paralelo ao diagnóstico; colite invasiva não deve ser tratada somente com antidiarreico. [2]"], "es": ["Evaluar hidratación, sangrado, dolor y signos de peritonitis. Corregir pérdidas en paralelo al diagnóstico; una colitis invasiva no debe tratarse solo con antidiarreico. [2]"]},
    drugsFirstLine: {"pt": ["Esquema adulto elegível: tetraciclina 500 mg por via oral quatro vezes ao dia durante 10 dias. Tomar 1 hora antes ou 2 horas após alimentos ou laticínios. É contraindicada na gestação e em crianças menores de 8 anos. [1]", "Alternativa adulta: metronidazol 500–750 mg por via oral três vezes ao dia durante 5 dias. Escolher um esquema adequado; não associar rotineiramente tetraciclina e metronidazol. Seleção depende de contraindicações e disponibilidade local. [1]"], "es": ["Esquema adulto elegible: tetraciclina 500 mg por vía oral cuatro veces al día durante 10 días. Tomar 1 hora antes o 2 horas después de alimentos o lácteos. Está contraindicada en embarazo y en menores de 8 años. [1]", "Alternativa adulta: metronidazol 500–750 mg por vía oral tres veces al día durante 5 días. Elegir un esquema adecuado; no asociar rutinariamente tetraciclina y metronidazol. La selección depende de contraindicaciones y disponibilidad local. [1]"]},
    redFlags: {"pt": [], "es": []},
    monitoring: {"pt": ["Reavaliar hidratação, frequência das evacuações, sangue e resposta. Persistência exige revisão do diagnóstico, adesão e reinfecção. Reforçar saneamento, água segura e higiene após contato com fezes e animais. [2, 1]"], "es": ["Reevaluar hidratación, frecuencia de evacuaciones, sangre y respuesta. La persistencia exige revisar diagnóstico, adherencia y reinfección. Reforzar saneamiento, agua segura e higiene tras contacto con heces y animales. [2, 1]"]},
    differentialDiagnosis: {"pt": [], "es": []},
    complications: {"pt": [], "es": []},
  ),
  ProtocolModel(
    id: "ascaridiase",
    canonicalProtocolId: "ascaridiase",
    title: {"pt": "Ascaridíase", "es": "Ascariasis"},
    severity: {"pt": "Avaliar sinais de alarme", "es": "Evaluar signos de alarma"},
    definition: {"pt": "Helmintíase intestinal por Ascaris; carga elevada pode causar obstrução e migração biliar.", "es": "Helmintiasis intestinal por Ascaris; una carga elevada puede causar obstrucción y migración biliar."},
    actions: {"pt": ["Helmintíase intestinal por Ascaris; carga elevada pode causar obstrução e migração biliar. [1]", "Pode ser assintomática ou causar desconforto abdominal; sintomas respiratórios transitórios podem ocorrer durante migração larvária. [1]", "Pesquisar ovos nas fezes conforme contexto; dor focal ou sinais obstrutivos exigem investigação por imagem e diagnóstico diferencial. [1]", "Tratar infecção e orientar saneamento/higiene; abdome agudo não deve ser manejado apenas com vermífugo ambulatorial. [1]", "Adulto com infecção não complicada: albendazol 400 mg por via oral em dose única, com estômago vazio, conforme referência CDC. [1]", "Avaliar resolução e reinfecção em áreas endêmicas; retorno se vômitos persistentes, dor progressiva ou distensão. [1]", "Obstrução, peritonismo, icterícia febril ou pancreatite suspeita exigem hospital e avaliação cirúrgica/endoscópica. [1]", "Gestação e crianças pequenas exigem avaliação específica de risco/benefício e autorização local; recomendações de campanhas coletivas não equivalem a prescrição individual. [1]"], "es": ["Helmintiasis intestinal por Ascaris; una carga elevada puede causar obstrucción y migración biliar. [1]", "Puede ser asintomática o causar molestias abdominales; pueden aparecer síntomas respiratorios transitorios durante migración larvaria. [1]", "Buscar huevos en heces según contexto; dolor focal o signos obstructivos exigen imagen y diagnóstico diferencial. [1]", "Tratar infección y orientar saneamiento/higiene; un abdomen agudo no debe manejarse solo con antiparasitario ambulatorio. [1]", "Adulto con infección no complicada: albendazol 400 mg por vía oral en dosis única, con estómago vacío, según referencia CDC. [1]", "Evaluar resolución y reinfección en áreas endémicas; retorno si vómitos persistentes, dolor progresivo o distensión. [1]", "Obstrucción, peritonismo, ictericia febril o sospecha de pancreatitis requieren hospital y valoración quirúrgica/endoscópica. [1]", "Embarazo y niños pequeños exigen evaluación específica de riesgo/beneficio y autorización local; recomendaciones de campañas colectivas no equivalen a prescripción individual. [1]"]},
    avoid: {},
    drugs: [],
    physiopathology: {"pt": "A infecção não complicada e a complicação mecânica exigem respostas distintas. Eliminar o helminto não resolve necessariamente uma obstrução já estabelecida, e sintomas biliares precisam de investigação dirigida. Essa separação determina a escolha entre tratamento ambulatorial e avaliação hospitalar.", "es": "La infección no complicada y la complicación mecánica requieren respuestas distintas. Eliminar el helminto no resuelve necesariamente una obstrucción establecida y los síntomas biliares necesitan un estudio dirigido. Esta separación determina la elección entre tratamiento ambulatorio y evaluación hospitalaria."},
    references: {"pt": ["[1] CDC. Clinical care of soil-transmitted helminths. 2024. https://www.cdc.gov/sth/hcp/clinical-care/index.html"], "es": ["[1] CDC. Clinical care of soil-transmitted helminths. 2024. https://www.cdc.gov/sth/hcp/clinical-care/index.html"]},
    exams: {"pt": ["Pesquisar ovos nas fezes conforme contexto; dor focal ou sinais obstrutivos exigem investigação por imagem e diagnóstico diferencial. [1]"], "es": ["Buscar huevos en heces según contexto; dolor focal o signos obstructivos exigen imagen y diagnóstico diferencial. [1]"]},
    classification: {"pt": [], "es": []},
    scenarios: {"pt": ["Obstrução, peritonismo, icterícia febril ou pancreatite suspeita exigem hospital e avaliação cirúrgica/endoscópica. [1]", "Gestação e crianças pequenas exigem avaliação específica de risco/benefício e autorização local; recomendações de campanhas coletivas não equivalem a prescrição individual. [1]"], "es": ["Obstrucción, peritonismo, ictericia febril o sospecha de pancreatitis requieren hospital y valoración quirúrgica/endoscópica. [1]", "Embarazo y niños pequeños exigen evaluación específica de riesgo/beneficio y autorización local; recomendaciones de campañas colectivas no equivalen a prescripción individual. [1]"]},
    objectives: {"pt": ["Pode ser assintomática ou causar desconforto abdominal; sintomas respiratórios transitórios podem ocorrer durante migração larvária. [1]"], "es": ["Puede ser asintomática o causar molestias abdominales; pueden aparecer síntomas respiratorios transitorios durante migración larvaria. [1]"]},
    drugsFirstLine: {"pt": ["Tratar infecção e orientar saneamento/higiene; abdome agudo não deve ser manejado apenas com vermífugo ambulatorial. [1]", "Adulto com infecção não complicada: albendazol 400 mg por via oral em dose única, com estômago vazio, conforme referência CDC. [1]"], "es": ["Tratar infección y orientar saneamiento/higiene; un abdomen agudo no debe manejarse solo con antiparasitario ambulatorio. [1]", "Adulto con infección no complicada: albendazol 400 mg por vía oral en dosis única, con estómago vacío, según referencia CDC. [1]"]},
