  ProtocolModel(
    id: "teniase",
    canonicalProtocolId: "teniase",
    title: {"pt": "Teníase intestinal", "es": "Teniasis intestinal"},
    severity: {"pt": "Avaliar sinais de alarme", "es": "Evaluar signos de alarma"},
    definition: {"pt": "Infecção intestinal pela tênia adulta; não é neurocisticercose. Identificar espécie ajuda a orientar risco e controle de transmissão.", "es": "Infección intestinal por tenia adulta; no es neurocisticercosis. Identificar especie ayuda a orientar riesgo y control de transmisión."},
    actions: {"pt": ["Infecção intestinal pela tênia adulta; não é neurocisticercose. Identificar espécie ajuda a orientar risco e controle de transmissão. [2]", "Eliminação de proglotes, desconforto abdominal ou infecção assintomática; perguntar convulsões, cefaleia e sintomas visuais antes do tratamento. [2, 1]", "Pesquisar ovos/proglotes em fezes; ovos isolados não distinguem todas as espécies. Sintomas neurológicos exigem investigação específica. [2]", "Tratar a forma intestinal e orientar higiene, preparo adequado de carnes e manejo epidemiológico; evitar automedicação se suspeita de cisticercose. [1, 2]", "Praziquantel 5–10 mg/kg por via oral em dose única; 10 mg/kg pode aumentar cura. Confirmar peso e apresentação antes de calcular comprimidos. [1]", "Reexaminar fezes após 1 e 3 meses para confirmar eliminação; manter orientação de prevenção de reinfecção. [1]", "Convulsão, déficit focal, hipertensão intracraniana ou queixa ocular exigem avaliação antes de antiparasitário, pelo risco de reação inflamatória em cisticercose. [1]", "Gestação, lactação e crianças requerem avaliação individual; tratamento intestinal não substitui protocolo de neurocisticercose. [1]"], "es": ["Infección intestinal por tenia adulta; no es neurocisticercosis. Identificar especie ayuda a orientar riesgo y control de transmisión. [2]", "Eliminación de proglótides, molestias abdominales o infección asintomática; preguntar convulsiones, cefalea y síntomas visuales antes del tratamiento. [2, 1]", "Buscar huevos/proglótides en heces; huevos aislados no distinguen todas las especies. Los síntomas neurológicos exigen investigación específica. [2]", "Tratar la forma intestinal y orientar higiene, preparación adecuada de carnes y manejo epidemiológico; evitar automedicación si se sospecha cisticercosis. [1, 2]", "Praziquantel 5–10 mg/kg por vía oral en dosis única; 10 mg/kg puede aumentar curación. Confirmar peso y presentación antes de calcular comprimidos. [1]", "Reexaminar heces después de 1 y 3 meses para confirmar eliminación; mantener orientación de prevención de reinfección. [1]", "Convulsión, déficit focal, hipertensión intracraneal o síntomas oculares requieren evaluación antes de antiparasitario, por riesgo de reacción inflamatoria en cisticercosis. [1]", "Embarazo, lactancia y niños requieren evaluación individual; tratamiento intestinal no sustituye protocolo de neurocisticercosis. [1]"]},
    avoid: {},
    drugs: [],
    physiopathology: {"pt": "O verme adulto no intestino e a doença por larvas em tecidos não são intercambiáveis. A investigação neurológica ou ocular antes do tratamento, quando há sintomas sugestivos, procura evitar que a terapia intestinal seja aplicada a uma situação com riscos inflamatórios distintos.", "es": "El gusano adulto intestinal y la enfermedad por larvas en tejidos no son intercambiables. La evaluación neurológica u ocular antes del tratamiento, cuando hay síntomas sugestivos, busca evitar que la terapia intestinal se aplique a una situación con riesgos inflamatorios distintos."},
    references: {"pt": ["[1] CDC. Clinical treatment of taeniasis. 2024. https://www.cdc.gov/taeniasis/hcp/clinical-care/index.html", "[2] CDC. Clinical overview of taeniasis. 2024. https://www.cdc.gov/taeniasis/hcp/clinical-overview/index.html"], "es": ["[1] CDC. Clinical treatment of taeniasis. 2024. https://www.cdc.gov/taeniasis/hcp/clinical-care/index.html", "[2] CDC. Clinical overview of taeniasis. 2024. https://www.cdc.gov/taeniasis/hcp/clinical-overview/index.html"]},
    exams: {"pt": ["Pesquisar ovos/proglotes em fezes; ovos isolados não distinguem todas as espécies. Sintomas neurológicos exigem investigação específica. [2]"], "es": ["Buscar huevos/proglótides en heces; huevos aislados no distinguen todas las especies. Los síntomas neurológicos exigen investigación específica. [2]"]},
    classification: {"pt": [], "es": []},
    scenarios: {"pt": ["Convulsão, déficit focal, hipertensão intracraniana ou queixa ocular exigem avaliação antes de antiparasitário, pelo risco de reação inflamatória em cisticercose. [1]", "Gestação, lactação e crianças requerem avaliação individual; tratamento intestinal não substitui protocolo de neurocisticercose. [1]"], "es": ["Convulsión, déficit focal, hipertensión intracraneal o síntomas oculares requieren evaluación antes de antiparasitario, por riesgo de reacción inflamatoria en cisticercosis. [1]", "Embarazo, lactancia y niños requieren evaluación individual; tratamiento intestinal no sustituye protocolo de neurocisticercosis. [1]"]},
    objectives: {"pt": ["Eliminação de proglotes, desconforto abdominal ou infecção assintomática; perguntar convulsões, cefaleia e sintomas visuais antes do tratamento. [2, 1]"], "es": ["Eliminación de proglótides, molestias abdominales o infección asintomática; preguntar convulsiones, cefalea y síntomas visuales antes del tratamiento. [2, 1]"]},
    drugsFirstLine: {"pt": ["Tratar a forma intestinal e orientar higiene, preparo adequado de carnes e manejo epidemiológico; evitar automedicação se suspeita de cisticercose. [1, 2]", "Praziquantel 5–10 mg/kg por via oral em dose única; 10 mg/kg pode aumentar cura. Confirmar peso e apresentação antes de calcular comprimidos. [1]"], "es": ["Tratar la forma intestinal y orientar higiene, preparación adecuada de carnes y manejo epidemiológico; evitar automedicación si se sospecha cisticercosis. [1, 2]", "Praziquantel 5–10 mg/kg por vía oral en dosis única; 10 mg/kg puede aumentar curación. Confirmar peso y presentación antes de calcular comprimidos. [1]"]},
