  ProtocolModel(
    id: "difilobotriase",
    canonicalProtocolId: "difilobotriase",
    title: {"pt": "Difilobotríase — infecção por tênia do peixe", "es": "Difilobotriasis — infección por tenia del pescado"},
    severity: {"pt": "Avaliar sinais de alarme", "es": "Evaluar signos de alarma"},
    definition: {"pt": "Infecção intestinal por cestódeos difilobotrídeos adquirida pelo consumo de peixe infectado cru ou malcozido. Pode ser assintomática ou causar desconforto gastrointestinal; não equivale à teníase por carne bovina ou suína.", "es": "Infección intestinal por cestodos difilobótridos adquirida al consumir pescado infectado crudo o poco cocido. Puede ser asintomática o causar molestias gastrointestinales; no equivale a teniasis por carne bovina o porcina."},
    actions: {"pt": ["Infecção intestinal por cestódeos difilobotrídeos adquirida pelo consumo de peixe infectado cru ou malcozido. Pode ser assintomática ou causar desconforto gastrointestinal; não equivale à teníase por carne bovina ou suína. [2]", "Pesquisar ovos ou proglotes nas fezes e solicitar identificação laboratorial. História de consumo de peixe orienta a hipótese, mas não substitui confirmação; ovos isolados nem sempre permitem identificação exata da espécie. [2]", "Avaliar sintomas, estado nutricional e sinais de obstrução. Anemia ou sintomas neurológicos exigem investigação adicional, sem atribuir automaticamente todas as manifestações à parasitose. [2]", "Praziquantel 5–10 mg/kg por via oral em dose única, com líquido durante refeição. Calcular pelo peso e conferir apresentação. Não confundir esta dose com esquemas de outros cestódeos ou de esquistossomose. [1]", "Niclosamida é alternativa conforme disponibilidade local e avaliação médica. O tratamento deve incluir orientação sobre preparo seguro do peixe e prevenção de reinfecção; não usar substâncias caseiras para expulsar o parasita. [1, 2]", "Reavaliar resolução dos sintomas e necessidade de confirmação parasitológica de cura conforme contexto. Persistência exige verificar adesão, identificação do agente e reinfecção antes de repetir tratamento. [1, 2]", "Vômitos persistentes, distensão, dor intensa ou sinais de obstrução exigem avaliação urgente. Infecção intestinal não complicada pode ser manejada ambulatorialmente com retorno definido. [2]", "Em menores de 4 anos, a bula e o contexto exigem avaliação específica do praziquantel. Gestação e lactação requerem decisão individual; recomendações para campanhas coletivas não constituem prescrição automática. [1]"], "es": ["Infección intestinal por cestodos difilobótridos adquirida al consumir pescado infectado crudo o poco cocido. Puede ser asintomática o causar molestias gastrointestinales; no equivale a teniasis por carne bovina o porcina. [2]", "Buscar huevos o proglótides en materia fecal y solicitar identificación de laboratorio. La historia de consumo de pescado orienta la hipótesis, pero no sustituye la confirmación; los huevos aislados no siempre permiten identificar la especie exacta. [2]", "Evaluar síntomas, estado nutricional y signos de obstrucción. La anemia o síntomas neurológicos requieren evaluación adicional, sin atribuir automáticamente todas las manifestaciones a la parasitosis. [2]", "Praziquantel 5–10 mg/kg por vía oral en dosis única, con líquido durante una comida. Calcular según peso y verificar presentación. No confundir esta dosis con esquemas de otros cestodos o de esquistosomiasis. [1]", "Niclosamida es una alternativa según disponibilidad local y evaluación médica. El tratamiento debe incluir orientación sobre preparación segura del pescado y prevención de reinfección; no usar sustancias caseras para expulsar el parásito. [1, 2]", "Reevaluar resolución de síntomas y necesidad de confirmación parasitológica de curación según contexto. La persistencia exige verificar adherencia, identificación del agente y reinfección antes de repetir tratamiento. [1, 2]", "Vómitos persistentes, distensión, dolor intenso o signos de obstrucción requieren evaluación urgente. La infección intestinal no complicada puede manejarse ambulatoriamente con seguimiento definido. [2]", "En menores de 4 años, la ficha técnica y el contexto requieren evaluación específica de praziquantel. Embarazo y lactancia exigen una decisión individual; las recomendaciones para campañas colectivas no constituyen prescripción automática. [1]"]},
    avoid: {},
    drugs: [],
    physiopathology: {"pt": "A identificação do cestódeo e a exposição alimentar ajudam a distinguir a tênia do peixe das tênias associadas a outras carnes. A prescrição é por peso, enquanto o seguimento verifica recuperação e prevenção de reinfecção; sintomas persistentes exigem revisar a causa.", "es": "La identificación del cestodo y la exposición alimentaria ayudan a distinguir la tenia del pescado de las asociadas a otras carnes. La prescripción depende del peso, mientras que el seguimiento verifica recuperación y prevención de reinfección; los síntomas persistentes exigen revisar la causa."},
    references: {"pt": ["[1] CDC. Clinical Care of Diphyllobothriid Tapeworm Infection. 2024. https://www.cdc.gov/diphyllobothrium/hcp/clinical-care/index.html", "[2] CDC. DPDx: Diphyllobothriasis. 2026. https://www.cdc.gov/dpdx/diphyllobothriasis/index.html"], "es": ["[1] CDC. Clinical Care of Diphyllobothriid Tapeworm Infection. 2024. https://www.cdc.gov/diphyllobothrium/hcp/clinical-care/index.html", "[2] CDC. DPDx: Diphyllobothriasis. 2026. https://www.cdc.gov/dpdx/diphyllobothriasis/index.html"]},
    exams: {"pt": ["Pesquisar ovos ou proglotes nas fezes e solicitar identificação laboratorial. História de consumo de peixe orienta a hipótese, mas não substitui confirmação; ovos isolados nem sempre permitem identificação exata da espécie. [2]"], "es": ["Buscar huevos o proglótides en materia fecal y solicitar identificación de laboratorio. La historia de consumo de pescado orienta la hipótesis, pero no sustituye la confirmación; los huevos aislados no siempre permiten identificar la especie exacta. [2]"]},
    classification: {"pt": [], "es": []},
    scenarios: {"pt": ["Vômitos persistentes, distensão, dor intensa ou sinais de obstrução exigem avaliação urgente. Infecção intestinal não complicada pode ser manejada ambulatorialmente com retorno definido. [2]", "Em menores de 4 anos, a bula e o contexto exigem avaliação específica do praziquantel. Gestação e lactação requerem decisão individual; recomendações para campanhas coletivas não constituem prescrição automática. [1]"], "es": ["Vómitos persistentes, distensión, dolor intenso o signos de obstrucción requieren evaluación urgente. La infección intestinal no complicada puede manejarse ambulatoriamente con seguimiento definido. [2]", "En menores de 4 años, la ficha técnica y el contexto requieren evaluación específica de praziquantel. Embarazo y lactancia exigen una decisión individual; las recomendaciones para campañas colectivas no constituyen prescripción automática. [1]"]},
    objectives: {"pt": ["Avaliar sintomas, estado nutricional e sinais de obstrução. Anemia ou sintomas neurológicos exigem investigação adicional, sem atribuir automaticamente todas as manifestações à parasitose. [2]"], "es": ["Evaluar síntomas, estado nutricional y signos de obstrucción. La anemia o síntomas neurológicos requieren evaluación adicional, sin atribuir automáticamente todas las manifestaciones a la parasitosis. [2]"]},
    drugsFirstLine: {"pt": ["Praziquantel 5–10 mg/kg por via oral em dose única, com líquido durante refeição. Calcular pelo peso e conferir apresentação. Não confundir esta dose com esquemas de outros cestódeos ou de esquistossomose. [1]", "Niclosamida é alternativa conforme disponibilidade local e avaliação médica. O tratamento deve incluir orientação sobre preparo seguro do peixe e prevenção de reinfecção; não usar substâncias caseiras para expulsar o parasita. [1, 2]"], "es": ["Praziquantel 5–10 mg/kg por vía oral en dosis única, con líquido durante una comida. Calcular según peso y verificar presentación. No confundir esta dosis con esquemas de otros cestodos o de esquistosomiasis. [1]", "Niclosamida es una alternativa según disponibilidad local y evaluación médica. El tratamiento debe incluir orientación sobre preparación segura del pescado y prevención de reinfección; no usar sustancias caseras para expulsar el parásito. [1, 2]"]},
    redFlags: {"pt": [], "es": []},
    monitoring: {"pt": ["Reavaliar resolução dos sintomas e necessidade de confirmação parasitológica de cura conforme contexto. Persistência exige verificar adesão, identificação do agente e reinfecção antes de repetir tratamento. [1, 2]"], "es": ["Reevaluar resolución de síntomas y necesidad de confirmación parasitológica de curación según contexto. La persistencia exige verificar adherencia, identificación del agente y reinfección antes de repetir tratamiento. [1, 2]"]},
