  ProtocolModel(
    id: "sindrome_intestino_curto",
    canonicalProtocolId: "sindrome_intestino_curto",
    title: {"pt": "Síndrome do intestino curto", "es": "Síndrome de intestino corto"},
    severity: {"pt": "Avaliar sinais de alarme", "es": "Evaluar signos de alarma"},
    definition: {"pt": "Redução ou dano extenso do delgado causa absorção insuficiente; a capacidade depende dos segmentos remanescentes e da continuidade do cólon. Nem todo intestino curto implica dependência parenteral permanente.", "es": "La reducción o daño extenso del intestino delgado causa absorción insuficiente; la capacidad depende de los segmentos remanentes y continuidad del colon. No todo intestino corto implica dependencia parenteral permanente."},
    actions: {"pt": ["Redução ou dano extenso do delgado causa absorção insuficiente; a capacidade depende dos segmentos remanescentes e da continuidade do cólon. Nem todo intestino curto implica dependência parenteral permanente. [1, 2]", "Rever relatório cirúrgico, anatomia, estoma, ingestão, perdas e suporte. Exames avaliam deficiências e complicações. [1]", "Avaliar desidratação, diurese, função renal e eletrólitos; comparar débito intestinal ao basal. Aumento agudo exige procurar infecção ou outra complicação. [1, 2]", "Individualizar dieta, solução de reidratação e suporte enteral ou parenteral. Reabilitação busca otimizar absorção e reduzir dependência de suporte quando seguro. [1]", "Antissecretores e antimotilidade podem ser usados conforme anatomia e resposta. Doses elevadas não devem ser copiadas sem supervisão; terapias de reabilitação intestinal requerem centro especializado. [2]", "Acompanhar peso, perdas, eletrólitos, micronutrientes e complicações renais ou hepáticas; ajustar suporte conforme evolução. [1]", "Incapacidade de compensar perdas, lesão renal, distúrbio eletrolítico ou suspeita de sepse exige hospital. Alta requer plano de hidratação e suporte viável. [1, 2]", "Crianças precisam acompanhamento de crescimento; gestação e doença orgânica associada modificam necessidades. Não usar uma dieta universal para todas as anatomias. [1, 2]"], "es": ["La reducción o daño extenso del intestino delgado causa absorción insuficiente; la capacidad depende de los segmentos remanentes y continuidad del colon. No todo intestino corto implica dependencia parenteral permanente. [1, 2]", "Revisar informe quirúrgico, anatomía, ostomía, ingesta, pérdidas y soporte. Los estudios evalúan carencias y complicaciones. [1]", "Evaluar deshidratación, diuresis, función renal y electrolitos; comparar débito intestinal con el basal. El aumento agudo exige buscar infección u otra complicación. [1, 2]", "Individualizar dieta, solución de rehidratación y soporte enteral o parenteral. La rehabilitación busca optimizar absorción y reducir dependencia de soporte cuando sea seguro. [1]", "Pueden usarse antisecretores y antimotilidad según anatomía y respuesta. Las dosis elevadas no deben copiarse sin supervisión; las terapias de rehabilitación intestinal requieren centro especializado. [2]", "Vigilar peso, pérdidas, electrolitos, micronutrientes y complicaciones renales o hepáticas; ajustar soporte según evolución. [1]", "Incapacidad de compensar pérdidas, lesión renal, trastorno electrolítico o sospecha de sepsis requiere hospital. El alta exige plan de hidratación y soporte viable. [1, 2]", "Los niños requieren seguimiento del crecimiento; embarazo y enfermedad orgánica asociada modifican necesidades. No usar una dieta universal para todas las anatomías. [1, 2]"]},
    avoid: {},
    drugs: [],
    physiopathology: {"pt": "A anatomia remanescente determina quais perdas e deficiências predominam. Assim, um plano que funciona para determinada configuração de estoma ou continuidade colônica pode ser inadequado para outra. A redução do suporte deve acompanhar capacidade funcional comprovada, não apenas melhora subjetiva.", "es": "La anatomía remanente determina qué pérdidas y deficiencias predominan. Por eso un plan útil para determinada configuración de estoma o continuidad colónica puede ser inadecuado para otra. La reducción del soporte debe acompañar una capacidad funcional demostrada, no solo una mejoría subjetiva."},
    references: {"pt": ["[1] NIDDK. Short Bowel Syndrome. 2026. https://www.niddk.nih.gov/health-information/digestive-diseases/short-bowel-syndrome", "[2] AGA. Management of short bowel syndrome. 2022. https://gastro.org/clinical-guidance/management-of-short-bowel-syndrome-sbs/", "[3] ESPEN. ESPEN guideline on chronic intestinal failure in adults — Update 2023. 2023. https://www.espen.org/files/ESPEN-Guidelines/ESPEN_guideline_on_chronic_intestinal_failure_in_adults.pdf"], "es": ["[1] NIDDK. Short Bowel Syndrome. 2026. https://www.niddk.nih.gov/health-information/digestive-diseases/short-bowel-syndrome", "[2] AGA. Management of short bowel syndrome. 2022. https://gastro.org/clinical-guidance/management-of-short-bowel-syndrome-sbs/", "[3] ESPEN. ESPEN guideline on chronic intestinal failure in adults — Update 2023. 2023. https://www.espen.org/files/ESPEN-Guidelines/ESPEN_guideline_on_chronic_intestinal_failure_in_adults.pdf"]},
    exams: {"pt": ["Rever relatório cirúrgico, anatomia, estoma, ingestão, perdas e suporte. Exames avaliam deficiências e complicações. [1]"], "es": ["Revisar informe quirúrgico, anatomía, ostomía, ingesta, pérdidas y soporte. Los estudios evalúan carencias y complicaciones. [1]"]},
    classification: {"pt": [], "es": []},
    scenarios: {"pt": ["Incapacidade de compensar perdas, lesão renal, distúrbio eletrolítico ou suspeita de sepse exige hospital. Alta requer plano de hidratação e suporte viável. [1, 2]", "Crianças precisam acompanhamento de crescimento; gestação e doença orgânica associada modificam necessidades. Não usar uma dieta universal para todas as anatomias. [1, 2]"], "es": ["Incapacidad de compensar pérdidas, lesión renal, trastorno electrolítico o sospecha de sepsis requiere hospital. El alta exige plan de hidratación y soporte viable. [1, 2]", "Los niños requieren seguimiento del crecimiento; embarazo y enfermedad orgánica asociada modifican necesidades. No usar una dieta universal para todas las anatomías. [1, 2]"]},
