  ProtocolModel(
    id: "doenca_inflamatoria_intestinal_nao_classificada",
    canonicalProtocolId: "doenca_inflamatoria_intestinal_nao_classificada",
    title: {"pt": "Doença inflamatória intestinal não classificada / colite indeterminada", "es": "Enfermedad inflamatoria intestinal no clasificada / colitis indeterminada"},
    severity: {"pt": "Avaliar sinais de alarme", "es": "Evaluar signos de alarma"},
    definition: {"pt": "Termo provisório quando a avaliação não distingue com segurança Crohn de retocolite ulcerativa. Colite indeterminada é tradicionalmente um termo anatomopatológico; não confundir com qualquer colite ainda sem investigação.", "es": "Término provisional cuando la evaluación no distingue con seguridad Crohn de colitis ulcerosa. Colitis indeterminada es tradicionalmente un término anatomopatológico; no confundir con cualquier colitis aún no estudiada."},
    actions: {"pt": ["Termo provisório quando a avaliação não distingue com segurança Crohn de retocolite ulcerativa. Colite indeterminada é tradicionalmente um termo anatomopatológico; não confundir com qualquer colite ainda sem investigação. [1]", "Revisar histologia, distribuição endoscópica, imagem do delgado e causas infecciosas ou medicamentosas. Manter a incerteza documentada; reavaliar a classificação conforme surgem novas evidências. [1]", "Tratar conforme fenótipo, extensão e gravidade, com especialista. A decisão cirúrgica reconstrutiva exige esclarecimento do risco de Crohn. [1]", "Colite com toxicidade sistêmica, dilatação, sangramento importante ou sinais peritoneais exige internação. A incerteza diagnóstica não deve atrasar estabilização. [1]"], "es": ["Término provisional cuando la evaluación no distingue con seguridad Crohn de colitis ulcerosa. Colitis indeterminada es tradicionalmente un término anatomopatológico; no confundir con cualquier colitis aún no estudiada. [1]", "Revisar histología, distribución endoscópica, imagen del intestino delgado y causas infecciosas o farmacológicas. Mantener documentada la incertidumbre; reevaluar la clasificación a medida que aparezcan nuevas evidencias. [1]", "Tratar según fenotipo, extensión y gravedad, con un especialista. Las decisiones quirúrgicas reconstructivas requieren aclarar el riesgo de Crohn. [1]", "La colitis con toxicidad sistémica, dilatación, sangrado importante o signos peritoneales requiere internación. La incertidumbre diagnóstica no debe retrasar la estabilización. [1]"]},
    avoid: {},
    drugs: [],
    physiopathology: {"pt": "A incerteza classificatória deve permanecer explícita até que clínica, endoscopia e histologia permitam maior definição. Um rótulo provisório não dispensa avaliar gravidade ou excluir infecção. O diagnóstico pode ser refinado no seguimento sem inventar uma etiologia separada.", "es": "La incertidumbre clasificatoria debe permanecer explícita hasta que clínica, endoscopia e histología permitan mayor definición. Una etiqueta provisional no exime de evaluar gravedad o excluir infección. El diagnóstico puede precisarse durante el seguimiento sin inventar una etiología separada."},
    references: {"pt": ["[1] BSG. British Society of Gastroenterology guidelines on inflammatory bowel disease in adults. 2025. https://gut.bmj.com/content/74/Suppl_2/s1/"], "es": ["[1] BSG. British Society of Gastroenterology guidelines on inflammatory bowel disease in adults. 2025. https://gut.bmj.com/content/74/Suppl_2/s1/"]},
    exams: {"pt": ["Revisar histologia, distribuição endoscópica, imagem do delgado e causas infecciosas ou medicamentosas. Manter a incerteza documentada; reavaliar a classificação conforme surgem novas evidências. [1]"], "es": ["Revisar histología, distribución endoscópica, imagen del intestino delgado y causas infecciosas o farmacológicas. Mantener documentada la incertidumbre; reevaluar la clasificación a medida que aparezcan nuevas evidencias. [1]"]},
