  ProtocolModel(
    id: "colite_microscopica",
    canonicalProtocolId: "colite_microscopica",
    title: {"pt": "Colite microscópica: colagenosa e linfocítica", "es": "Colitis microscópica: colágena y linfocítica"},
    severity: {"pt": "Avaliar sinais de alarme", "es": "Evaluar signos de alarma"},
    definition: {"pt": "Causa de diarreia aquosa crônica, geralmente sem sangue, com colonoscopia macroscopicamente normal ou quase normal. Colagenosa e linfocítica são subtipos histológicos, não duplicatas independentes.", "es": "Causa de diarrea acuosa crónica, generalmente sin sangre, con colonoscopia macroscópicamente normal o casi normal. La colágena y linfocítica son subtipos histológicos, no duplicados independientes."},
    actions: {"pt": ["Causa de diarreia aquosa crônica, geralmente sem sangue, com colonoscopia macroscopicamente normal ou quase normal. Colagenosa e linfocítica são subtipos histológicos, não duplicatas independentes. [1]", "Obter biópsias do cólon direito e esquerdo mesmo se a mucosa parecer normal. Revisar fármacos associados e investigar doença celíaca; calprotectina normal não exclui o diagnóstico. [1]", "Adulto com doença ativa: budesonida oral 9 mg uma vez ao dia por 6 a 8 semanas para indução. Recorrência pode exigir manutenção individual na menor dose eficaz, com gastroenterologia. [1]", "Verificar formulação e interações; budesonida não é isenta de efeitos sistêmicos. Hepatopatia, inibidores de CYP3A4 e exposição prolongada aumentam preocupações com supressão adrenal e saúde óssea. [2]", "Reavaliar frequência e consistência das fezes e hidratação. Sangue, febre ou dor progressiva exigem buscar outro diagnóstico; refratariedade requer rever diagnóstico e causas associadas. [1]"], "es": ["Causa de diarrea acuosa crónica, generalmente sin sangre, con colonoscopia macroscópicamente normal o casi normal. La colágena y linfocítica son subtipos histológicos, no duplicados independientes. [1]", "Obtener biopsias del colon derecho e izquierdo aunque la mucosa parezca normal. Revisar fármacos asociados e investigar enfermedad celíaca; una calprotectina normal no descarta el diagnóstico. [1]", "Adulto con enfermedad activa: budesonida oral 9 mg una vez al día durante 6 a 8 semanas para inducción. La recurrencia puede requerir mantenimiento individual a la menor dosis eficaz, con gastroenterología. [1]", "Verificar formulación e interacciones; la budesonida no está exenta de efectos sistémicos. La hepatopatía, los inhibidores de CYP3A4 y la exposición prolongada aumentan la preocupación por supresión suprarrenal y salud ósea. [2]", "Reevaluar frecuencia y consistencia de las heces e hidratación. La sangre, fiebre o dolor progresivo requieren buscar otro diagnóstico; la refractariedad exige revisar el diagnóstico y las causas asociadas. [1]"]},
