  ProtocolModel(
    id: "colite_isquemica",
    canonicalProtocolId: "colite_isquemica",
    title: {"pt": "Colite isquêmica", "es": "Colitis isquémica"},
    severity: {"pt": "Avaliar sinais de alarme", "es": "Evaluar signos de alarma"},
    definition: {"pt": "Redução do fluxo colônico causando lesão mucosa, frequentemente com dor e hematoquezia. Pode ser transitória ou evoluir para necrose; não é sinônimo de oclusão da artéria mesentérica.", "es": "Reducción del flujo colónico que causa lesión mucosa, frecuentemente con dolor y hematoquecia. Puede ser transitoria o evolucionar a necrosis; no es sinónimo de oclusión de la arteria mesentérica."},
    actions: {"pt": ["Redução do fluxo colônico causando lesão mucosa, frequentemente com dor e hematoquezia. Pode ser transitória ou evoluir para necrose; não é sinônimo de oclusão da artéria mesentérica. [2]", "Tomografia com contraste e avaliação clínica inicial. Colonoscopia precoce, idealmente em até 48 horas, pode confirmar em pacientes adequadamente selecionados; evitar se houver peritonite ou suspeita de gangrena. [1]", "Corrigir hipovolemia e precipitantes, manter vigilância hemodinâmica e avaliar gravidade. Dor intensa sem sangramento ou acometimento direito exige considerar isquemia mesentérica aguda e angiotomografia. [1, 3]", "Casos leves costumam responder a suporte. Doença moderada ou grave pode exigir antibióticos e avaliação cirúrgica; necrose, perfuração ou peritonite exigem cirurgia urgente. [1]", "Acompanhar dor, sangramento, hemograma, função renal e sinais de deterioração. Sintomas persistentes ou recorrentes exigem reavaliação e investigação de estenose ou diagnóstico alternativo. [2]"], "es": ["Reducción del flujo colónico que causa lesión mucosa, frecuentemente con dolor y hematoquecia. Puede ser transitoria o evolucionar a necrosis; no es sinónimo de oclusión de la arteria mesentérica. [2]", "Tomografía con contraste y evaluación clínica inicial. La colonoscopia temprana, idealmente dentro de 48 horas, puede confirmar en pacientes adecuadamente seleccionados; evitarla ante peritonitis o sospecha de gangrena. [1]", "Corregir hipovolemia y desencadenantes, mantener vigilancia hemodinámica y evaluar gravedad. El dolor intenso sin sangrado o compromiso derecho requieren considerar isquemia mesentérica aguda y angiotomografía. [1, 3]", "Los casos leves suelen responder al sostén. La enfermedad moderada o grave puede requerir antibióticos y evaluación quirúrgica; la necrosis, perforación o peritonitis requieren cirugía urgente. [1]", "Controlar dolor, sangrado, hemograma, función renal y signos de deterioro. Los síntomas persistentes o recurrentes requieren reevaluación e investigación de estenosis o diagnóstico alternativo. [2]"]},
