  ProtocolModel(
    id: "lesao_intestinal_radiacao",
    canonicalProtocolId: "lesao_intestinal_radiacao",
    title: {"pt": "Lesão intestinal por radiação: enterite, colite e proctopatia", "es": "Lesión intestinal por radiación: enteritis, colitis y proctopatía"},
    severity: {"pt": "Avaliar sinais de alarme", "es": "Evaluar signos de alarma"},
    definition: {"pt": "Lesão aguda da mucosa ou lesão tardia vascular e fibrótica após radioterapia abdominal ou pélvica. O segmento acometido define enterite, colite ou proctopatia; as condutas não são todas intercambiáveis.", "es": "Lesión aguda de la mucosa o lesión tardía vascular y fibrótica tras radioterapia abdominal o pélvica. El segmento afectado define enteritis, colitis o proctopatía; no todas las conductas son intercambiables."},
    actions: {"pt": ["Lesão aguda da mucosa ou lesão tardia vascular e fibrótica após radioterapia abdominal ou pélvica. O segmento acometido define enterite, colite ou proctopatia; as condutas não são todas intercambiáveis. [1, 2]", "Relacionar sintomas ao campo e à data da radioterapia, mas excluir infecção, recorrência tumoral e outras causas. Sangramento persistente requer avaliação endoscópica especializada; imagem é importante se houver obstrução ou fístula. [1, 2]", "Avaliar hidratação, anemia, nutrição e gravidade da dor. Não atribuir abdome agudo à radioterapia sem excluir perfuração ou isquemia. [1]", "Suporte nutricional e tratamento dirigido aos mecanismos da diarreia. Proctopatia crônica hemorrágica pode responder a enemas de sucralfato ou tratamento endoscópico com plasma de argônio em serviço experiente; casos selecionados podem receber oxigenoterapia hiperbárica. [1, 2]", "Internar diante de sangramento com repercussão, obstrução, perfuração, desidratação grave ou impossibilidade de manter nutrição. Casos estáveis exigem seguimento conjunto com oncologia e gastroenterologia. [1, 2]"], "es": ["Lesión aguda de la mucosa o lesión tardía vascular y fibrótica tras radioterapia abdominal o pélvica. El segmento afectado define enteritis, colitis o proctopatía; no todas las conductas son intercambiables. [1, 2]", "Relacionar los síntomas con el campo y la fecha de radioterapia, pero descartar infección, recurrencia tumoral y otras causas. El sangrado persistente requiere evaluación endoscópica especializada; las imágenes son importantes ante obstrucción o fístula. [1, 2]", "Evaluar hidratación, anemia, nutrición y gravedad del dolor. No atribuir un abdomen agudo a la radioterapia sin descartar perforación o isquemia. [1]", "Soporte nutricional y tratamiento dirigido a los mecanismos de la diarrea. La proctopatía crónica hemorrágica puede responder a enemas de sucralfato o tratamiento endoscópico con plasma de argón en un servicio experimentado; casos seleccionados pueden recibir oxigenoterapia hiperbárica. [1, 2]", "Internar ante sangrado con repercusión, obstrucción, perforación, deshidratación grave o imposibilidad de mantener la nutrición. Los casos estables requieren seguimiento conjunto con oncología y gastroenterología. [1, 2]"]},
    avoid: {},
    drugs: [],
    physiopathology: {"pt": "O sítio irradiado e o intervalo clínico orientam a interpretação dos sintomas. Enterite, colite e proctite não são termos terapêuticos intercambiáveis: uma intervenção endoscópica para sangramento retal não trata automaticamente a disfunção absortiva do delgado.", "es": "El sitio irradiado y el contexto temporal orientan la interpretación de los síntomas. Enteritis, colitis y proctitis no son términos terapéuticos intercambiables: una intervención endoscópica para sangrado rectal no trata automáticamente la disfunción absortiva del intestino delgado."},
    references: {"pt": ["[1] NCI. Radiation Enteritis. 2025. https://www.cancer.gov/about-cancer/treatment/side-effects/radiation-enteritis", "[2] ASCRS. Treatment of Chronic Radiation Proctitis. 2018. https://www.ascrsu.com/ascrs/view/ASCRS-Toolkit/2851049/all/Treatment_of_Chronic_Radiation_Proctitis"], "es": ["[1] NCI. Radiation Enteritis. 2025. https://www.cancer.gov/about-cancer/treatment/side-effects/radiation-enteritis", "[2] ASCRS. Treatment of Chronic Radiation Proctitis. 2018. https://www.ascrsu.com/ascrs/view/ASCRS-Toolkit/2851049/all/Treatment_of_Chronic_Radiation_Proctitis"]},
    exams: {"pt": ["Relacionar sintomas ao campo e à data da radioterapia, mas excluir infecção, recorrência tumoral e outras causas. Sangramento persistente requer avaliação endoscópica especializada; imagem é importante se houver obstrução ou fístula. [1, 2]"], "es": ["Relacionar los síntomas con el campo y la fecha de radioterapia, pero descartar infección, recurrencia tumoral y otras causas. El sangrado persistente requiere evaluación endoscópica especializada; las imágenes son importantes ante obstrucción o fístula. [1, 2]"]},
    classification: {"pt": [], "es": []},
    scenarios: {"pt": ["Internar diante de sangramento com repercussão, obstrução, perfuração, desidratação grave ou impossibilidade de manter nutrição. Casos estáveis exigem seguimento conjunto com oncologia e gastroenterologia. [1, 2]"], "es": ["Internar ante sangrado con repercusión, obstrucción, perforación, deshidratación grave o imposibilidad de mantener la nutrición. Los casos estables requieren seguimiento conjunto con oncología y gastroenterología. [1, 2]"]},
    objectives: {"pt": ["Avaliar hidratação, anemia, nutrição e gravidade da dor. Não atribuir abdome agudo à radioterapia sem excluir perfuração ou isquemia. [1]"], "es": ["Evaluar hidratación, anemia, nutrición y gravedad del dolor. No atribuir un abdomen agudo a la radioterapia sin descartar perforación o isquemia. [1]"]},
    drugsFirstLine: {"pt": ["Suporte nutricional e tratamento dirigido aos mecanismos da diarreia. Proctopatia crônica hemorrágica pode responder a enemas de sucralfato ou tratamento endoscópico com plasma de argônio em serviço experiente; casos selecionados podem receber oxigenoterapia hiperbárica. [1, 2]"], "es": ["Soporte nutricional y tratamiento dirigido a los mecanismos de la diarrea. La proctopatía crónica hemorrágica puede responder a enemas de sucralfato o tratamiento endoscópico con plasma de argón en un servicio experimentado; casos seleccionados pueden recibir oxigenoterapia hiperbárica. [1, 2]"]},
