  ProtocolModel(
    id: "proctite_infecciosa",
    canonicalProtocolId: "proctite_infecciosa",
    title: {"pt": "Proctite infecciosa", "es": "Proctitis infecciosa"},
    severity: {"pt": "Avaliar sinais de alarme", "es": "Evaluar signos de alarma"},
    definition: {"pt": "Inflamação retal infecciosa com dor, tenesmo ou secreção. Considerar gonococo, clamídia, herpes e sífilis conforme exposição.", "es": "Inflamación rectal infecciosa con dolor, tenesmo o secreción. Considerar gonococo, clamidia, herpes y sífilis según la exposición."},
    actions: {"pt": ["Inflamação retal infecciosa com dor, tenesmo ou secreção. Considerar gonococo, clamídia, herpes e sífilis conforme exposição. [1]", "Realizar avaliação anorretal, testes retais para gonococo e clamídia, investigação de herpes em úlceras e sorologias para sífilis e HIV. [1]", "Terapia empírica indicada no adulto: ceftriaxona 500 mg intramuscular em dose única, mais doxiciclina 100 mg oral a cada 12 horas por 7 dias. Peso de pelo menos 150 kg: ceftriaxona 1 g. [1]", "Clamídia retal positiva com quadro sugestivo de linfogranuloma venéreo: prolongar doxiciclina para 21 dias. Gestação, alergia importante ou úlceras dolorosas exigem adaptação específica. [1]", "Avaliar parceiros; evitar contato sexual até conclusão do tratamento e resolução dos sintomas. Após gonorreia ou clamídia, retestar em 3 meses. [1]", "Na proctite aguda com exposição anal receptiva, iniciar terapia presumível se houver exsudato anorretal ou leucócitos na secreção; se anuscopia ou Gram não estiverem disponíveis, apresentação compatível também pode justificar tratar enquanto se aguardam exames. Úlceras dolorosas exigem avaliar tratamento concomitante para herpes. [1]"], "es": ["Inflamación rectal infecciosa con dolor, tenesmo o secreción. Considerar gonococo, clamidia, herpes y sífilis según la exposición. [1]", "Realizar evaluación anorrectal, pruebas rectales para gonococo y clamidia, estudio de herpes en úlceras y serologías para sífilis y VIH. [1]", "Tratamiento empírico indicado en el adulto: ceftriaxona 500 mg intramuscular en dosis única, más doxiciclina 100 mg oral cada 12 horas durante 7 días. Peso de al menos 150 kg: ceftriaxona 1 g. [1]", "Clamidia rectal positiva con cuadro sugestivo de linfogranuloma venéreo: prolongar doxiciclina a 21 días. El embarazo, alergia importante o úlceras dolorosas requieren adaptación específica. [1]", "Evaluar a las parejas; evitar contacto sexual hasta completar el tratamiento y resolver los síntomas. Tras gonorrea o clamidia, repetir pruebas a los 3 meses. [1]", "En proctitis aguda con exposición anal receptiva, iniciar tratamiento presuntivo ante exudado anorrectal o leucocitos en la secreción; si no se dispone de anoscopia o Gram, una presentación compatible también puede justificar tratar mientras se esperan los estudios. Las úlceras dolorosas requieren evaluar tratamiento concomitante para herpes. [1]"]},
