  ProtocolModel(
    id: "diverticulose_2026",
    canonicalProtocolId: "diverticulose_2026",
    title: {"pt": "Diverticulose e doença diverticular sintomática não complicada", "es": "Diverticulosis y enfermedad diverticular sintomática no complicada"},
    severity: {"pt": "Avaliar sinais de alarme", "es": "Evaluar signos de alarma"},
    definition: {"pt": "Diverticulose é a presença de divertículos colônicos, muitas vezes incidental. Sintomas crônicos atribuídos a divertículos, sem inflamação aguda ou complicação, constituem um ramo clínico diferente da diverticulite.", "es": "La diverticulosis es la presencia de divertículos colónicos, a menudo incidental. Los síntomas crónicos atribuidos a divertículos, sin inflamación aguda ni complicaciones, constituyen una rama clínica diferente de la diverticulitis."},
    actions: {"pt": ["Diverticulose é a presença de divertículos colônicos, muitas vezes incidental. Sintomas crônicos atribuídos a divertículos, sem inflamação aguda ou complicação, constituem um ramo clínico diferente da diverticulite. [2]", "Não atribuir toda dor à diverticulose encontrada em colonoscopia. Considerar síndrome do intestino irritável, câncer e colite; febre ou dor focal aguda exige investigar diverticulite. [1]", "Diverticulose assintomática não exige antibiótico. Na doença sintomática sem diverticulite, priorizar alimentação com fibras conforme tolerância, líquidos adequados, atividade física e manejo da constipação; evitar antibióticos rotineiros. [1]", "Reavaliar sintomas persistentes e sinais de alarme. Sangramento, perda ponderal, anemia ou mudança progressiva do hábito intestinal exigem investigação específica. [2, 1]"], "es": ["La diverticulosis es la presencia de divertículos colónicos, a menudo incidental. Los síntomas crónicos atribuidos a divertículos, sin inflamación aguda ni complicaciones, constituyen una rama clínica diferente de la diverticulitis. [2]", "No atribuir todo dolor a la diverticulosis hallada en una colonoscopia. Considerar síndrome de intestino irritable, cáncer y colitis; la fiebre o dolor focal agudo requieren investigar diverticulitis. [1]", "La diverticulosis asintomática no requiere antibióticos. En la enfermedad sintomática sin diverticulitis, priorizar alimentación con fibra según tolerancia, líquidos adecuados, actividad física y manejo del estreñimiento; evitar antibióticos rutinarios. [1]", "Reevaluar síntomas persistentes y signos de alarma. El sangrado, pérdida de peso, anemia o cambio progresivo del hábito intestinal requieren estudio específico. [2, 1]"]},
    avoid: {},
    drugs: [],
    physiopathology: {"pt": "A presença anatômica de divertículos não demonstra que eles sejam a causa de qualquer dor. Distinguir achado incidental, sintomas persistentes e inflamação aguda evita antibióticos desnecessários e mantém aberta a investigação de outros diagnósticos.", "es": "La presencia anatómica de divertículos no demuestra que causen cualquier dolor. Distinguir hallazgo incidental, síntomas persistentes e inflamación aguda evita antibióticos innecesarios y mantiene abierta la investigación de otros diagnósticos."},
    references: {"pt": ["[1] NICE. Diverticular disease: diagnosis and management, NG147. 2019. https://www.nice.org.uk/guidance/ng147/chapter/Recommendations", "[2] NIDDK. Diverticular Disease. 2021. https://www.niddk.nih.gov/health-information/digestive-diseases/diverticulosis-diverticulitis"], "es": ["[1] NICE. Diverticular disease: diagnosis and management, NG147. 2019. https://www.nice.org.uk/guidance/ng147/chapter/Recommendations", "[2] NIDDK. Diverticular Disease. 2021. https://www.niddk.nih.gov/health-information/digestive-diseases/diverticulosis-diverticulitis"]},
    exams: {"pt": ["Não atribuir toda dor à diverticulose encontrada em colonoscopia. Considerar síndrome do intestino irritável, câncer e colite; febre ou dor focal aguda exige investigar diverticulite. [1]"], "es": ["No atribuir todo dolor a la diverticulosis hallada en una colonoscopia. Considerar síndrome de intestino irritable, cáncer y colitis; la fiebre o dolor focal agudo requieren investigar diverticulitis. [1]"]},
