  ProtocolModel(
    id: "obstrucao_adesiva_delgado_asbo",
    canonicalProtocolId: "obstrucao_adesiva_delgado_asbo",
    title: {"pt": "Obstrução do intestino delgado por aderências", "es": "Obstrucción del intestino delgado por adherencias"},
    severity: {"pt": "Avaliar sinais de alarme", "es": "Evaluar signos de alarma"},
    definition: {"pt": "Aderências após cirurgia ou inflamação podem produzir bloqueio mecânico parcial ou completo. Episódios prévios não tornam uma nova crise automaticamente benigna.", "es": "Las adherencias tras cirugía o inflamación pueden producir un bloqueo mecánico parcial o completo. Los episodios previos no hacen que una nueva crisis sea automáticamente benigna."},
    actions: {"pt": ["Aderências após cirurgia ou inflamação podem produzir bloqueio mecânico parcial ou completo. Episódios prévios não tornam uma nova crise automaticamente benigna. [2]", "Manter jejum, obter acesso venoso, corrigir perdas e eletrólitos e administrar analgesia. Descompressão por sonda é indicada conforme vômitos, distensão e risco de aspiração; solicitar avaliação cirúrgica precoce. [1]", "Tomografia com contraste intravenoso, quando apropriada, identifica nível, causa e sinais de isquemia. Hemograma, eletrólitos, função renal e lactato ajudam a avaliar gravidade; lactato normal não exclui sofrimento intestinal. [1]", "Peritonismo, dor contínua crescente, choque, alça fechada ou sinais de isquemia/perfuração exigem intervenção urgente. Obstrução confirmada exige cuidado hospitalar e reavaliação clínica seriada. [1]", "Na ausência de peritonite, estrangulamento ou isquemia, pode-se tentar tratamento conservador hospitalar. Um período de até 72 horas é frequentemente aceitável em pacientes estáveis, mas deterioração exige cirurgia antes disso. Contraste hidrossolúvel pode auxiliar a decisão em protocolo supervisionado. [1]", "Registrar dor, exame abdominal, diurese, débito da sonda e trânsito intestinal. Alta somente após resolução clínica, tolerância alimentar e plano de retorno; explicar risco de recorrência. [2]"], "es": ["Las adherencias tras cirugía o inflamación pueden producir un bloqueo mecánico parcial o completo. Los episodios previos no hacen que una nueva crisis sea automáticamente benigna. [2]", "Mantener ayuno, obtener acceso venoso, corregir pérdidas y electrolitos y administrar analgesia. La descompresión con sonda se indica según vómitos, distensión y riesgo de aspiración; solicitar evaluación quirúrgica temprana. [1]", "La tomografía con contraste intravenoso, cuando corresponde, identifica nivel, causa y signos de isquemia. El hemograma, electrolitos, función renal y lactato ayudan a evaluar la gravedad; un lactato normal no descarta sufrimiento intestinal. [1]", "El peritonismo, dolor continuo creciente, choque, asa cerrada o signos de isquemia/perforación requieren intervención urgente. La obstrucción confirmada requiere atención hospitalaria y reevaluación clínica seriada. [1]", "En ausencia de peritonitis, estrangulación o isquemia puede intentarse tratamiento conservador hospitalario. Un período de hasta 72 horas suele ser aceptable en pacientes estables, pero el deterioro requiere cirugía antes. El contraste hidrosoluble puede ayudar en la decisión dentro de un protocolo supervisado. [1]", "Registrar dolor, examen abdominal, diuresis, débito de la sonda y tránsito intestinal. Dar el alta solo tras la resolución clínica, tolerancia alimentaria y plan de regreso; explicar el riesgo de recurrencia. [2]"]},
    avoid: {},
    drugs: [],
    physiopathology: {"pt": "Uma história cirúrgica favorece aderências, mas não elimina outras causas. Observação conservadora é uma estratégia ativa com exames seriados e critérios de falha. Um período máximo de tentativa não autoriza esperar diante de deterioração ou sinais de sofrimento intestinal.", "es": "Un antecedente quirúrgico favorece adherencias, pero no elimina otras causas. La observación conservadora es una estrategia activa con exámenes seriados y criterios de fracaso. Un período máximo de intento no autoriza esperar ante deterioro o signos de sufrimiento intestinal."},
    references: {"pt": ["[1] WSES. Bologna guidelines for adhesive small bowel obstruction: 2017 update. 2018. https://pmc.ncbi.nlm.nih.gov/articles/PMC6006983/", "[2] NIDDK. Abdominal Adhesions. 2019. https://www.niddk.nih.gov/health-information/digestive-diseases/abdominal-adhesions"], "es": ["[1] WSES. Bologna guidelines for adhesive small bowel obstruction: 2017 update. 2018. https://pmc.ncbi.nlm.nih.gov/articles/PMC6006983/", "[2] NIDDK. Abdominal Adhesions. 2019. https://www.niddk.nih.gov/health-information/digestive-diseases/abdominal-adhesions"]},
    exams: {"pt": ["Tomografia com contraste intravenoso, quando apropriada, identifica nível, causa e sinais de isquemia. Hemograma, eletrólitos, função renal e lactato ajudam a avaliar gravidade; lactato normal não exclui sofrimento intestinal. [1]"], "es": ["La tomografía con contraste intravenoso, cuando corresponde, identifica nivel, causa y signos de isquemia. El hemograma, electrolitos, función renal y lactato ayudan a evaluar la gravedad; un lactato normal no descarta sufrimiento intestinal. [1]"]},
    classification: {"pt": [], "es": []},
    scenarios: {"pt": ["Peritonismo, dor contínua crescente, choque, alça fechada ou sinais de isquemia/perfuração exigem intervenção urgente. Obstrução confirmada exige cuidado hospitalar e reavaliação clínica seriada. [1]"], "es": ["El peritonismo, dolor continuo creciente, choque, asa cerrada o signos de isquemia/perforación requieren intervención urgente. La obstrucción confirmada requiere atención hospitalaria y reevaluación clínica seriada. [1]"]},
    objectives: {"pt": ["Manter jejum, obter acesso venoso, corrigir perdas e eletrólitos e administrar analgesia. Descompressão por sonda é indicada conforme vômitos, distensão e risco de aspiração; solicitar avaliação cirúrgica precoce. [1]"], "es": ["Mantener ayuno, obtener acceso venoso, corregir pérdidas y electrolitos y administrar analgesia. La descompresión con sonda se indica según vómitos, distensión y riesgo de aspiración; solicitar evaluación quirúrgica temprana. [1]"]},
    drugsFirstLine: {"pt": ["Na ausência de peritonite, estrangulamento ou isquemia, pode-se tentar tratamento conservador hospitalar. Um período de até 72 horas é frequentemente aceitável em pacientes estáveis, mas deterioração exige cirurgia antes disso. Contraste hidrossolúvel pode auxiliar a decisão em protocolo supervisionado. [1]"], "es": ["En ausencia de peritonitis, estrangulación o isquemia puede intentarse tratamiento conservador hospitalario. Un período de hasta 72 horas suele ser aceptable en pacientes estables, pero el deterioro requiere cirugía antes. El contraste hidrosoluble puede ayudar en la decisión dentro de un protocolo supervisado. [1]"]},
