  ProtocolModel(
    id: "ileo_paralitico",
    canonicalProtocolId: "ileo_paralitico",
    title: {"pt": "Íleo paralítico", "es": "Íleo paralítico"},
    severity: {"pt": "Avaliar sinais de alarme", "es": "Evaluar signos de alarma"},
    definition: {"pt": "Redução transitória da propulsão intestinal sem ponto de bloqueio mecânico; pode ocorrer após cirurgia, infecção, distúrbios eletrolíticos ou fármacos.", "es": "Reducción transitoria de la propulsión intestinal sin un punto de bloqueo mecánico; puede ocurrir tras cirugía, infección, alteraciones electrolíticas o fármacos."},
    actions: {"pt": ["Redução transitória da propulsão intestinal sem ponto de bloqueio mecânico; pode ocorrer após cirurgia, infecção, distúrbios eletrolíticos ou fármacos. [1]", "Examinar, revisar medicações e eletrólitos e obter imagem se houver dúvida de obstrução, complicação pós-operatória ou isquemia. Ausculta isolada não distingue com segurança íleo de obstrução. [1]", "Tratar a causa, corrigir eletrólitos, reduzir opioides e anticolinérgicos quando possível e estimular mobilização apropriada. Sonda e restrição oral dependem de vômitos e distensão; não usar neostigmina automaticamente como se todo íleo fosse Ogilvie. [1, 2]", "Dor focal crescente, peritonismo, febre ou deterioração exigem rever imediatamente o diagnóstico e envolver cirurgia. Retomar dieta conforme recuperação e tolerância, sem prolongar jejum desnecessariamente. [1]"], "es": ["Reducción transitoria de la propulsión intestinal sin un punto de bloqueo mecánico; puede ocurrir tras cirugía, infección, alteraciones electrolíticas o fármacos. [1]", "Examinar, revisar medicamentos y electrolitos y obtener imágenes si hay dudas sobre obstrucción, complicación posoperatoria o isquemia. La auscultación aislada no distingue con seguridad íleo de obstrucción. [1]", "Tratar la causa, corregir electrolitos, reducir opioides y anticolinérgicos cuando sea posible y favorecer la movilización apropiada. La sonda y restricción oral dependen de vómitos y distensión; no usar neostigmina automáticamente como si todo íleo fuera Ogilvie. [1, 2]", "El dolor focal creciente, peritonismo, fiebre o deterioro requieren revisar inmediatamente el diagnóstico e involucrar a cirugía. Reiniciar la alimentación según recuperación y tolerancia, sin prolongar el ayuno innecesariamente. [1]"]},
    avoid: {},
    drugs: [],
    physiopathology: {"pt": "A parada funcional do trânsito pode reproduzir sintomas de bloqueio mecânico. A distinção muda a conduta: corrigir precipitantes é central no íleo, enquanto uma obstrução mecânica pode exigir intervenção. A evolução clínica deve ser coerente com o diagnóstico inicialmente proposto.", "es": "La detención funcional del tránsito puede reproducir síntomas de bloqueo mecánico. La distinción modifica la conducta: corregir precipitantes es central en el íleo, mientras que una obstrucción mecánica puede exigir intervención. La evolución clínica debe ser coherente con el diagnóstico inicialmente propuesto."},
    references: {"pt": ["[1] NCI. Gastrointestinal Complications PDQ. 2026. https://www.cancer.gov/about-cancer/treatment/side-effects/constipation/gi-complications-hp-pdq", "[2] NIDDK. Treatment for Intestinal Pseudo-obstruction. 2021. https://www.niddk.nih.gov/health-information/digestive-diseases/intestinal-pseudo-obstruction/treatment"], "es": ["[1] NCI. Gastrointestinal Complications PDQ. 2026. https://www.cancer.gov/about-cancer/treatment/side-effects/constipation/gi-complications-hp-pdq", "[2] NIDDK. Treatment for Intestinal Pseudo-obstruction. 2021. https://www.niddk.nih.gov/health-information/digestive-diseases/intestinal-pseudo-obstruction/treatment"]},
    exams: {"pt": ["Examinar, revisar medicações e eletrólitos e obter imagem se houver dúvida de obstrução, complicação pós-operatória ou isquemia. Ausculta isolada não distingue com segurança íleo de obstrução. [1]"], "es": ["Examinar, revisar medicamentos y electrolitos y obtener imágenes si hay dudas sobre obstrucción, complicación posoperatoria o isquemia. La auscultación aislada no distingue con seguridad íleo de obstrucción. [1]"]},
    classification: {"pt": [], "es": []},
    scenarios: {"pt": ["Dor focal crescente, peritonismo, febre ou deterioração exigem rever imediatamente o diagnóstico e envolver cirurgia. Retomar dieta conforme recuperação e tolerância, sem prolongar jejum desnecessariamente. [1]"], "es": ["El dolor focal creciente, peritonismo, fiebre o deterioro requieren revisar inmediatamente el diagnóstico e involucrar a cirugía. Reiniciar la alimentación según recuperación y tolerancia, sin prolongar el ayuno innecesariamente. [1]"]},
