    references: {"pt": ["[1] NIDDK. Treatment for Intestinal Pseudo-obstruction. 2021. https://www.niddk.nih.gov/health-information/digestive-diseases/intestinal-pseudo-obstruction/treatment", "[2] NIDDK. Intestinal Pseudo-obstruction: Definition and Facts. 2021. https://www.niddk.nih.gov/health-information/digestive-diseases/intestinal-pseudo-obstruction/definition-facts"], "es": ["[1] NIDDK. Treatment for Intestinal Pseudo-obstruction. 2021. https://www.niddk.nih.gov/health-information/digestive-diseases/intestinal-pseudo-obstruction/treatment", "[2] NIDDK. Intestinal Pseudo-obstruction: Definition and Facts. 2021. https://www.niddk.nih.gov/health-information/digestive-diseases/intestinal-pseudo-obstruction/definition-facts"]},
