List<ProtocolModel> applyApprovedGiBatch01(List<ProtocolModel> existing) {
  final replacements = {for (final row in approvedGiBatch01NativeProjections) row.id: row};
  final output = <ProtocolModel>[];
  for (final original in existing) {
    final updated = replacements.remove(original.id);
    if (updated == null) { output.add(original); continue; }
    final preserveComplement = original.id == 'colite_estercoral_impactacao_fecal';
    Map<String, List<String>> merge(Map<String, List<String>>? old, Map<String, List<String>>? next) => {
      for (final lang in ['pt', 'es']) lang: [if (preserveComplement) ...?old?[lang], ...?next?[lang]],
    };
    output.add(ProtocolModel(
      id: original.id, canonicalFamilyId: original.canonicalFamilyId,
      canonicalProtocolId: updated.canonicalProtocolId,
      title: original.title, severity: original.severity,
      definition: updated.definition,
      recognize: original.recognize,
      actions: {for (final lang in ['pt','es']) lang: [if (preserveComplement) ...original.getActions(lang), ...updated.getActions(lang)]},
      avoid: preserveComplement ? original.avoid : updated.avoid,
      drugs: preserveComplement ? original.drugs : updated.drugs,
      physiopathology: preserveComplement ? original.physiopathology : updated.physiopathology,
      classification: updated.classification,
      severityCriteria: preserveComplement ? original.severityCriteria : null,
      redFlags: merge(original.redFlags, updated.redFlags),
      differentialDiagnosis: merge(original.differentialDiagnosis, updated.differentialDiagnosis),
      exams: merge(original.exams, updated.exams),
      objectives: merge(original.objectives, updated.objectives),
      drugsFirstLine: merge(original.drugsFirstLine, updated.drugsFirstLine),
      drugsSecondLine: preserveComplement ? original.drugsSecondLine : null,
      drugsConditional: preserveComplement ? original.drugsConditional : null,
      drugsContraindicated: preserveComplement ? original.drugsContraindicated : null,
      scenarios: merge(original.scenarios, updated.scenarios),
      monitoring: merge(original.monitoring, updated.monitoring),
      complications: merge(original.complications, updated.complications),
      doNotDo: preserveComplement ? original.doNotDo : null,
      pearls: preserveComplement ? original.pearls : null,
      references: merge(original.references, updated.references),
    ));
  }
  output.addAll(replacements.values);
  return List<ProtocolModel>.unmodifiable(output);
}
